package ca.humber.stockbridge.service;
import ca.humber.stockbridge.model.*;import ca.humber.stockbridge.repo.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@Service public class InventoryService {private final MaterialRepository materials;private final WarehouseRepository warehouses;private final SupplierRepository suppliers;private final StockLotRepository lots;private final PurchaseRepository purchases;private final SaleRepository sales;public InventoryService(MaterialRepository m,WarehouseRepository w,SupplierRepository s,StockLotRepository l,PurchaseRepository p,SaleRepository sa){materials=m;warehouses=w;suppliers=s;lots=l;purchases=p;sales=sa;}public BigDecimal available(Long m,Long w){return lots.findByMaterialIdAndWarehouseIdOrderByAcquiredAtAsc(m,w).stream().map(x->x.weightKg).reduce(BigDecimal.ZERO,BigDecimal::add);}public BigDecimal occupied(Long w){return lots.findByWarehouseId(w).stream().map(x->x.weightKg).reduce(BigDecimal.ZERO,BigDecimal::add);}@Transactional public void purchase(Long supplierId,Long materialId,Long warehouseId,BigDecimal kg,BigDecimal price,String user){validate(kg,price);Supplier s=suppliers.findById(supplierId).orElseThrow(()->new IllegalArgumentException("Select a valid supplier."));Material m=materials.findById(materialId).orElseThrow(()->new IllegalArgumentException("Select a valid material."));Warehouse w=warehouses.findById(warehouseId).orElseThrow(()->new IllegalArgumentException("Select a valid warehouse."));if(!w.active||occupied(w.id).add(kg).compareTo(w.capacityKg)>0)throw new IllegalArgumentException("Warehouse capacity would be exceeded.");Purchase p=new Purchase();p.supplier=s;p.material=m;p.warehouse=w;p.weightKg=kg;p.pricePerKg=price;p.totalCad=kg.multiply(price);p.createdBy=user;purchases.save(p);lots.save(new StockLot(m,w,s,kg));}@Transactional public void sell(String customer,Long materialId,Long warehouseId,BigDecimal kg,BigDecimal price,String user){validate(kg,price);if(customer==null||customer.isBlank())throw new IllegalArgumentException("Customer name is required.");Material m=materials.findById(materialId).orElseThrow(()->new IllegalArgumentException("Select a valid material."));Warehouse w=warehouses.findById(warehouseId).orElseThrow(()->new IllegalArgumentException("Select a valid warehouse."));if(available(materialId,warehouseId).compareTo(kg)<0)throw new IllegalArgumentException("Insufficient inventory at the selected warehouse.");BigDecimal remaining=kg;for(StockLot lot:lots.findByMaterialIdAndWarehouseIdOrderByAcquiredAtAsc(materialId,warehouseId)){BigDecimal take=lot.weightKg.min(remaining);lot.weightKg=lot.weightKg.subtract(take);lots.save(lot);remaining=remaining.subtract(take);if(remaining.signum()==0)break;}Sale sale=new Sale();sale.customerName=customer.trim();sale.material=m;sale.warehouse=w;sale.weightKg=kg;sale.pricePerKg=price;sale.totalCad=kg.multiply(price);sale.createdBy=user;sales.save(sale);}private void validate(BigDecimal kg,BigDecimal price){if(kg==null||kg.signum()<=0||kg.compareTo(new BigDecimal("1000000"))>0)throw new IllegalArgumentException("Weight must be between 0 and 1,000,000 kg.");if(price==null||price.signum()<0||price.compareTo(new BigDecimal("100000"))>0)throw new IllegalArgumentException("Price must be between 0 and 100,000 CAD/kg.");}}